<script setup lang="ts">
import {money} from '~/shared/types'
const {cart,quote,pending,error,refresh}=useCartQuote()
const confirmClear=ref(false)
useSeoMeta({title:'Корзина — Deadlock Family',robots:'noindex'})
</script>
<template><div class="container page"><div class="breadcrumbs"><NuxtLink to="/">Главная</NuxtLink><AppIcon name="chevron"/><span>Корзина</span></div><div class="section-heading"><div class="page-heading" style="margin:0"><span class="eyebrow">ВАШИ НАХОДКИ</span><h1>Корзина</h1></div><button v-if="cart.items.length" class="text-link" @click="confirmClear=true">Очистить корзину <AppIcon name="trash" :size="16"/></button></div><div v-if="error" class="notice error" role="alert">{{error}} <button class="text-link" @click="refresh">Повторить</button></div><ClientOnly><div v-if="!cart.items.length" class="empty-state"><AppIcon name="bag" :size="42"/><h2>Здесь ждут ваших находок</h2><p>В архиве есть кое-что, что может стать вашим любимым.</p><NuxtLink to="/shop" class="btn btn-primary">Заглянуть в магазин <AppIcon name="arrow"/></NuxtLink></div><div v-else class="split-layout"><div><div v-if="quote?.changed" class="notice" role="alert">Цены некоторых вещей изменились. Проверьте новые суммы перед оформлением.<div style="margin-top:10px"><button class="btn btn-small" @click="cart.acceptPrices(quote.items)">Принять новые цены</button></div></div><div v-if="quote&&!quote.valid" class="notice error" role="alert">Часть находок больше недоступна в выбранном количестве. Уменьшите количество или удалите их из корзины.</div><div :aria-busy="pending"><article v-for="line in quote?.items" :key="`${line.productId}:${line.variantId}`" class="cart-item"><img v-if="line.image" :src="line.image" :alt="line.name" width="110" height="100"><div><h3>{{line.name}}</h3><p>{{line.variantLabel}} · {{money(line.price)}} / шт.</p><span v-if="!line.available" class="status-pill" style="color:#e5a68f">Недоступно · остаток {{line.stock}}</span><div class="cart-line-actions"><div class="quantity"><button class="qty-button" :aria-label="`Уменьшить количество: ${line.name}`" :disabled="line.quantity<=1||pending" @click="cart.quantity(line.productId,line.variantId,line.quantity-1)"><AppIcon name="minus" :size="13"/></button><span aria-live="polite">{{line.quantity}}</span><button class="qty-button" :aria-label="`Увеличить количество: ${line.name}`" :disabled="line.quantity>=line.stock||line.quantity>=99||pending" @click="cart.quantity(line.productId,line.variantId,line.quantity+1)"><AppIcon name="plus" :size="13"/></button></div><button :aria-label="`Удалить ${line.name}`" @click="cart.remove(line.productId,line.variantId)">Удалить</button></div></div><div class="line-total">{{money(line.price*line.quantity)}}</div></article></div><NuxtLink to="/shop" class="text-link" style="margin-top:24px">Продолжить поиски <AppIcon name="arrow" :size="16"/></NuxtLink></div><aside class="summary-panel"><h2>Ваша история</h2><div class="summary-row"><span>Товары ({{cart.count}})</span><span>{{money(quote?.subtotal||0)}}</span></div><div class="summary-row"><span>Тестовая доставка</span><span>На следующем шаге</span></div><div class="summary-total"><span>Итого</span><span>{{money(quote?.subtotal||0)}}</span></div><button class="btn btn-primary" :disabled="pending||!quote?.valid||quote.changed||!!error" @click="navigateTo('/checkout')">К оформлению <AppIcon name="arrow" :size="18"/></button><small>Демонстрация · без оплаты и отправки</small></aside></div><template #fallback><div class="notice">Открываем вашу корзину…</div></template></ClientOnly><ConfirmDialog v-if="confirmClear" title="Освободить корзину?" message="Все выбранные вещи исчезнут из корзины. Вы сможете найти их снова в магазине." confirm-label="Очистить" @cancel="confirmClear=false" @confirm="cart.clear();confirmClear=false"/></div></template>
